import com.alibaba.fastjson2.*;
public class ParameterStringTest{
 public static void main(String[]args){JSONObject x=new JSONObject();x.put("empty","");x.put("kind","payment");JSONArray list=new JSONArray();list.add("");list.add("constant");x.put("values",list);x.put("integer",Long.valueOf(7));x.put("number",Double.valueOf(19.25));String before=x.toJSONString();TpccWeBridge.symbols.clear();TpccWeBridge.collect(x,"");if(!before.equals(x.toJSONString()))throw new AssertionError("Input value changed");for(String key:new String[]{"empty","kind"}){String value=x.getString(key);if(value==value.intern())throw new AssertionError("Still interned:"+key);}for(Object value:list)if(value==((String)value).intern())throw new AssertionError("Array string still interned");if(!TpccWeBridge.symbols.containsKey("empty")||!TpccWeBridge.symbols.containsKey("values_0"))throw new AssertionError("Symbol coverage changed");System.out.println("PASS exact JSON values; scalar/array String identities are fresh; empty values remain symbolized");}
}
